generated_pydough:
# Count students over 18 who do not have food or animal type allergies
result = students.WHERE(
    (age > 18) & 
    (HASNOT(has_allergies.WHERE(
        (allergy_type.allergytype == "food") | 
        (allergy_type.allergytype == "animal")
    )) == 1)
).CALCULATE(
    count_students = COUNT(students.stuid)
)

# Find people whose age is greater than any engineer's age, sorted by age
result = people.WHERE(
    age > MIN(people.WHERE(job == "engineer").age)
).CALCULATE(
    person_name = name
).ORDER_BY(age.ASC())

# Find the average grade of all students who have some friends
students_with_friends_avg_grade = highschoolers.WHERE(
    HAS(friends) == True
).CALCULATE(
    average_grade = AVG(grade)
)

# Find the course with the most students enrolled
course_with_most_students = course.WHERE(
    HAS(student_enrolment_course)
).CALCULATE(
    course_name=course_name,
    student_count=COUNT(student_enrolment_course)
).TOP_K(1, by=student_count.DESC()).CALCULATE(
    course_name=course_name
)

students_without_tv_lounge = students.WHERE(
    ~(lives_ins.dorm.dormid.ISIN(
        has_amenities.WHERE(dorm_amenity.amenity_name == "TV Lounge").dormid
    ))
).CALCULATE(
    first_name=fname,
    age=age
)

# Find professionals who performed below-average treatments
below_avg_professionals = dog_kennels.treatment.WHERE(
    cost_of_treatment < RELAVG(cost_of_treatment)
).professional.PARTITION(
    name="unique_professionals", 
    by=(first_name, last_name)
).CALCULATE(
    first_name = first_name,
    last_name = last_name
)

# Count how many dorms have each amenity and find the most common one
most_common_amenity = has_amenities.PARTITION(
    name="amenity_groups", 
    by=amenid
).CALCULATE(
    amenity_name=dorm_amenity.amenity_name,
    dorm_count=COUNT(has_amenities)
).TOP_K(1, by=dorm_count.DESC()).CALCULATE(
    amenity_name=amenity_name
)

# Find all movies that have at least one rating higher than the average James Cameron film rating
result = movies.WHERE(
    HAS(ratings.WHERE(
        stars > movies.WHERE(director == "James Cameron").ratings.CALCULATE(
            avg_rating=AVG(stars)
        ).avg_rating
    ))
).CALCULATE(
    title=title,
    director=director
)

# Find distinct customers who bought keyboards
keyboard_customers = customer.WHERE(
    HAS(customer_order.order_item.product.WHERE(
        product_name == "keyboard"
    ))
).CALCULATE(
    customer_name=customer_name
)

red_slow_products_count = product.WHERE(
    (ref_color.color_description == "red") &
    (HAS(product_characteristic.WHERE(characteristic.characteristic_name == "slow")) == 1)
).CALCULATE(
    count_products = COUNT(product.product_id)
)

# Find movies that have never been reviewed by Brittany Harris and calculate their average ratings
movies_without_brittany_reviews = ratings.WHERE(
    reviewer.name != "Brittany Harris"
).PARTITION(
    name="movie_groups", by=mid
).CALCULATE(
    movie_title=movie.title,
    average_rating=AVG(ratings.stars)
)

research_documents = document.WHERE(
    (grant.grant_amount > 5000) & 
    (grant.organisation.organisation_type_join.organisation_type_description == 'Research')
).CALCULATE(
    sent_date=sent_date
)

# Find the bike that traveled the most (most trips) in zip code 94002
most_traveled_bike = trips.WHERE(
    zip_code == 94002
).PARTITION(
    name="bike_groups", 
    by=bike_id
).CALCULATE(
    bike_id=bike_id,
    trip_count=COUNT(trips)
).TOP_K(1, by=trip_count.DESC()).CALCULATE(
    bike_id=bike_id
)

# Find the party email that has used party services the greatest number of times
most_active_party_email = party.WHERE(
    HAS(party_service) == 1
).CALCULATE(
    service_count=COUNT(party_service)
).TOP_K(1, by=service_count.DESC()).CALCULATE(
    party_email=party_email
)

# Find the maximum age among all engineers
max_engineer_age = network_2.people.WHERE(job == "engineer").CALCULATE(max_age=MAX(age))

# Count people whose age is greater than the maximum engineer age
result = network_2.CALCULATE(
    max_eng_age=max_engineer_age.SINGULAR().max_age
).people.WHERE(
    age > max_eng_age
).CALCULATE(
    count_people=COUNT(name)
)

# Calculate the average campus fee and count universities with fees above average
result = csu_fee.WHERE(
    campusfee > AVG(csu_fee.campusfee)
).CALCULATE(
    count_above_average = COUNT(csu_fee)
)

# Find the institution with the most papers
institution_with_most_papers = insts.WHERE(
    HAS(authorships) == 1
).CALCULATE(
    institution_name=name,
    paper_count=COUNT(authorships)
).TOP_K(1, by=paper_count.DESC()).CALCULATE(
    institution_name=institution_name
)

