)

# Find the maximum order quantity across all order items
max_quantity_result = Order_Items.CALCULATE(
    max_qty=MAX(order_quantity)
)

# Find customers who have order items with the maximum quantity
customers_with_max_quantity = Order_Items.WHERE(
